import geopandas as gpd
import networkx as nx
import numpy as np
import osmnx as ox
import pandas as pd

from .config import BNG, DERIVED, NORTH_PORTAL, PORTAL_DELAY_MIN, SOUTH_PORTAL, WALK_KMH, to_bng, tunnel_length_m

# %% ../nbs/03_access.ipynb #2bb85d56
def prepare(G: nx.MultiDiGraph, kmh: float, exclude=()) -> nx.Graph:
    "Undirected, projected to BNG, with a `minutes` edge weight. Drops edges on streets named in `exclude`."
    G = ox.project_graph(G, to_crs=BNG)
    U = nx.Graph()
    U.add_nodes_from(G.nodes(data=True))
    for u, v, d in G.edges(data=True):
        name = d.get("name", "")
        name = " / ".join(name) if isinstance(name, list) else str(name)
        if any(x in name for x in exclude):
            continue
        minutes = d["length"] / (kmh * 1000 / 60)
        if not U.has_edge(u, v) or U[u][v]["minutes"] > minutes:
            U.add_edge(u, v, minutes=minutes)
    return U


def nearest_node(G: nx.Graph, lonlat) -> int:
    "The node of `G` closest to a (lon, lat) point."
    x, y = to_bng(lonlat)
    xs = np.array([d["x"] for _, d in G.nodes(data=True)])
    ys = np.array([d["y"] for _, d in G.nodes(data=True)])
    return list(G.nodes)[int(np.argmin((xs - x) ** 2 + (ys - y) ** 2))]


def with_tunnel(G: nx.Graph, kmh: float) -> nx.Graph:
    "A copy of `G` with the tunnel added as one edge between the portals."
    H = G.copy()
    minutes = tunnel_length_m() / (kmh * 1000 / 60) + 2 * PORTAL_DELAY_MIN
    H.add_edge(nearest_node(G, SOUTH_PORTAL), nearest_node(G, NORTH_PORTAL), minutes=minutes)
    return H


def times_to(G: nx.Graph, lonlat) -> pd.Series:
    "Minutes from every node of `G` to the node nearest `lonlat`."
    return pd.Series(nx.single_source_dijkstra_path_length(G, nearest_node(G, lonlat), weight="minutes"))

# %% ../nbs/03_access.ipynb #e48f2091
ACCESS_COLS = ["walk_before", "walk_after", "pt_before", "pt_after", "access_before", "access_after"]
CYCLE_COLS = ["cycle_before", "cycle_after"]


def attach_access(points: gpd.GeoDataFrame) -> gpd.GeoDataFrame:
    "Before/after travel times from the nearest street node, joined onto `points` (returned in BNG)."
    path = DERIVED / "access_nodes.gpkg"
    walk = gpd.read_file(path, layer="walk_pt")[ACCESS_COLS + ["geometry"]]
    bike = gpd.read_file(path, layer="cycle")[CYCLE_COLS + ["geometry"]]
    pts = points.to_crs(BNG)
    for layer in (walk, bike):
        pts = gpd.sjoin_nearest(pts, layer, how="left").drop(columns="index_right")
        pts = pts[~pts.index.duplicated()]  # equidistant ties
    return pts
